/* PRONUNCIACIÓN */
const PRON = [{"group": "Lo básico", "items": [{"t": "Se lee casi como se escribe", "d": "Igual que en español, el italiano es muy regular: cada letra suena casi siempre igual. Si aprendes las pocas reglas de abajo, podrás leer cualquier palabra.", "ex": []}, {"t": "Las vocales: a, e, i, o, u", "d": "Suenan como en español, claras y completas. La única diferencia es que la <b>e</b> y la <b>o</b> pueden ser abiertas o cerradas según la palabra. Al principio no te preocupes: si las pronuncias como en español, se te entiende perfectamente.", "ex": [["casa", "CA-sa", "casa"], ["vino", "VI-no", "vino"], ["uno", "U-no", "uno"], ["bene", "BE-ne", "bien"], ["sole", "SO-le", "sol"]]}, {"t": "H: siempre muda", "d": "Como en español, la <b>h</b> no suena nunca. Solo sirve para cambiar el sonido de c y g (ver abajo) y en algunas formas del verbo <i>avere</i>.", "ex": [["ho", "o", "tengo"], ["hanno", "AN-no", "tienen"], ["hotel", "o-TEL", "hotel"]]}]}, {"group": "C y G: la regla más importante", "items": [{"t": "C + a, o, u = «k»", "d": "Delante de a, o, u la <b>c</b> suena como la c de «casa».", "ex": [["casa", "CA-sa", "casa"], ["cosa", "CO-sa", "cosa"], ["cucina", "cu-CHI-na", "cocina"]]}, {"t": "C + e, i = «ch»", "d": "Delante de e, i la <b>c</b> suena como la <b>ch</b> de «chico». ¡Nunca como la z española!", "ex": [["cena", "CHE-na", "cena"], ["cinema", "CHI-ne-ma", "cine"], ["dieci", "DIE-chi", "diez"]]}, {"t": "CI + vocal = «ch» (la i no suena)", "d": "En <b>cia, cio, ciu</b> la i es casi muda: solo indica que la c suena «ch».", "ex": [["ciao", "CHAO", "hola / adiós"], ["cioccolato", "chok-ko-LA-to", "chocolate"], ["camicia", "ca-MI-cha", "camisa"]]}, {"t": "CH = «k»", "d": "Al revés que en español: <b>ch</b> suena como «k». Se usa delante de e, i para mantener el sonido duro.", "ex": [["chiave", "KIA-ve", "llave"], ["che", "KE", "que / qué"], ["perché", "per-KE", "por qué / porque"]]}, {"t": "G + a, o, u = «g» de «gato»", "d": "Como en español.", "ex": [["gatto", "GAT-to", "gato"], ["gola", "GO-la", "garganta"], ["gusto", "GUS-to", "gusto"]]}, {"t": "G + e, i = «y» suave (como «dj»)", "d": "Delante de e, i la <b>g</b> suena como la <b>y</b> argentina suave o la «j» inglesa de <i>John</i>. ¡Nunca como la j española!", "ex": [["gelato", "dye-LA-to", "helado"], ["giro", "DYI-ro", "vuelta"], ["pagina", "PA-dyi-na", "página"]]}, {"t": "GI + vocal = «dy» (la i no suena)", "d": "En <b>gia, gio, giu</b> la i solo indica el sonido suave.", "ex": [["giallo", "DYAL-lo", "amarillo"], ["giorno", "DYOR-no", "día"], ["giugno", "DYU-ño", "junio"]]}, {"t": "GH = «g» de «guerra»", "d": "Delante de e, i, <b>gh</b> mantiene el sonido duro, como el «gue/gui» español.", "ex": [["spaghetti", "spa-GUET-ti", "espaguetis"], ["ghiaccio", "GUIA-cho", "hielo"], ["laghi", "LA-gui", "lagos"]]}]}, {"group": "Combinaciones especiales", "items": [{"t": "GN = «ñ»", "d": "Suena exactamente como la <b>ñ</b> española.", "ex": [["bagno", "BA-ño", "baño"], ["gnocchi", "ÑOK-ki", "ñoquis"], ["lasagna", "la-SA-ña", "lasaña"]]}, {"t": "GLI = «ll» (palatal)", "d": "Suena como la <b>ll</b> tradicional de algunas zonas de España, con la lengua pegada al paladar: algo entre «li» y «ll».", "ex": [["figlio", "FI-llo", "hijo"], ["famiglia", "fa-MI-lla", "familia"], ["aglio", "A-llo", "ajo"]]}, {"t": "SC + e, i = «sh»", "d": "Suena como «sh» en inglés (como cuando pides silencio: ¡shhh!).", "ex": [["pesce", "PE-she", "pescado"], ["uscire", "u-SHI-re", "salir"], ["sciare", "shi-A-re", "esquiar"]]}, {"t": "SC + a, o, u y SCH = «sk»", "d": "Delante de a, o, u (o con h) se pronuncian las dos letras: «s» + «k».", "ex": [["scuola", "SKUO-la", "escuela"], ["scarpa", "SKAR-pa", "zapato"], ["schiena", "SKIE-na", "espalda"]]}, {"t": "QU = «ku»", "d": "La <b>u</b> sí suena, como en «cuando».", "ex": [["quando", "KUAN-do", "cuándo"], ["quattro", "KUAT-tro", "cuatro"], ["acqua", "AK-kua", "agua"]]}]}, {"group": "Consonantes distintas al español", "items": [{"t": "Z = «ts» o «dz»", "d": "La <b>z</b> italiana nunca suena como la z española. Suena «ts» (como en <i>pizza</i>) o «dz» (como en <i>zero</i>). Las dos se entienden; con «ts» casi siempre acertarás.", "ex": [["pizza", "PIT-tsa", "pizza"], ["grazie", "GRA-tsie", "gracias"], ["zero", "DZE-ro", "cero"], ["zucchero", "DZUK-ke-ro", "azúcar"]]}, {"t": "S entre vocales = «s» sonora (como un zumbido)", "d": "En el norte de Italia la <b>s</b> entre dos vocales suena vibrando, como una abeja «zzz». En el sur suena como en español. Las dos formas son correctas.", "ex": [["casa", "CA-sa / CA-za", "casa"], ["rosa", "RO-sa / RO-za", "rosa"], ["chiesa", "KIE-za", "iglesia"]]}, {"t": "V ≠ B", "d": "En italiano la <b>v</b> suena como en francés o inglés: el labio inferior toca los dientes de arriba. Es distinta de la b.", "ex": [["vino", "VI-no", "vino"], ["vero", "VE-ro", "verdadero"], ["bevo", "BE-vo", "bebo"]]}, {"t": "R = como en español", "d": "Una <b>r</b> suena como la r de «pero»; <b>rr</b> suena fuerte, como en «perro».", "ex": [["caro", "CA-ro", "caro"], ["carro", "CAR-ro", "carro"], ["Roma", "RO-ma", "Roma"]]}]}, {"group": "Lo que más delata a un extranjero", "items": [{"t": "Las consonantes dobles se alargan", "d": "Muy importante: una consonante doble se mantiene un instante más (como si hicieras una pausa mínima). ¡Cambia el significado!", "ex": [["pala → palla", "PA-la / PAL-la", "pala → pelota"], ["caro → carro", "CA-ro / CAR-ro", "caro → carro"], ["sete → sette", "SE-te / SET-te", "sed → siete"], ["nono → nonno", "NO-no / NON-no", "noveno → abuelo"]]}, {"t": "La sílaba tónica", "d": "La mayoría de palabras llevan el acento en la penúltima sílaba. Si la última sílaba es tónica, se escribe con tilde (<i>città, perché, caffè</i>). Pero hay muchas palabras con acento antes que no llevan tilde: apréndelas escuchando.", "ex": [["città", "chit-TA", "ciudad"], ["caffè", "caf-FE", "café"], ["telefono", "te-LE-fo-no", "teléfono"], ["macchina", "MAK-ki-na", "coche"]]}, {"t": "La melodía", "d": "El italiano «canta» más que el español: las vocales tónicas se alargan un poco y las frases suben y bajan más. Imitar frases completas (no solo palabras) es la mejor forma de cogerlo.", "ex": [["Buongiorno! Come sta?", "buon-DYOR-no, CO-me STA", "¡Buenos días! ¿Cómo está?"], ["Che bello!", "ke BEL-lo", "¡Qué bonito!"], ["Andiamo a mangiare?", "an-DIA-mo a man-DYA-re", "¿Vamos a comer?"]]}]}];
